import { ProfilePatch } from './types';

const MAX_NAME = 40;
const MAX_TAGS = 5;
const MAX_TAG_LENGTH = 12;

function invalid(): never {
  throw new Error('invalid profile');
}

// Reads an own data property; accessors are rejected so parsing has no side effects.
function dataValue(target: object, key: string): unknown {
  const descriptor = Object.getOwnPropertyDescriptor(target, key);
  if (!descriptor || !('value' in descriptor)) return invalid();
  return descriptor.value;
}

function parseDisplayName(value: unknown): string | null {
  if (value === null) return null;
  if (typeof value !== 'string') return invalid();
  const trimmed = value.trim();
  if (trimmed.length < 1 || trimmed.length > MAX_NAME) return invalid();
  return trimmed;
}

function parseTags(value: unknown): string[] {
  if (value === null) return [];
  if (!Array.isArray(value)) return invalid();
  if (value.length > MAX_TAGS) return invalid();
  const result: string[] = [];
  const seen = new Set<string>();
  for (let i = 0; i < value.length; i++) {
    const item = dataValue(value, String(i));
    if (typeof item !== 'string') return invalid();
    const tag = item.trim();
    if (tag.length < 1 || tag.length > MAX_TAG_LENGTH || seen.has(tag)) return invalid();
    seen.add(tag);
    result.push(tag);
  }
  return result;
}

export function parseProfile(input: unknown): ProfilePatch {
  if (typeof input !== 'object' || input === null || Array.isArray(input)) return invalid();
  const proto = Object.getPrototypeOf(input);
  if (proto !== Object.prototype && proto !== null) return invalid();
  for (const key of Reflect.ownKeys(input)) {
    if (key !== 'displayName' && key !== 'tags') return invalid();
  }

  let displayName: ProfilePatch['displayName'] = { kind: 'keep' };
  let tags: ProfilePatch['tags'] = { kind: 'keep' };
  if (Object.prototype.hasOwnProperty.call(input, 'displayName')) {
    displayName = { kind: 'set', value: parseDisplayName(dataValue(input, 'displayName')) };
  }
  if (Object.prototype.hasOwnProperty.call(input, 'tags')) {
    tags = { kind: 'set', value: parseTags(dataValue(input, 'tags')) };
  }
  return { displayName, tags };
}
EOF
cat > src/service.ts <<'EOF'
import { Profile } from './types';
import { parseProfile } from './parser';
export class ProfileService {
  constructor(readonly profile: Profile) {}
  patch(input: unknown): Profile {
    // Parse and validate everything first so a failure leaves storage untouched.
    const parsed = parseProfile(input);
    if (parsed.displayName.kind === 'set') this.profile.displayName = parsed.displayName.value;
    if (parsed.tags.kind === 'set') this.profile.tags = [...parsed.tags.value];
    return { displayName: this.profile.displayName, tags: [...this.profile.tags] };
  }
}
